begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.uid(value integer) returns uuid language sql immutable as $$select ('31710000-0000-4000-8000-'||lpad(value::text,12,'0'))::uuid$$;
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at,raw_app_meta_data,raw_user_meta_data)
select pg_temp.uid(value),'authenticated','authenticated','s317-private-'||value||'@veyocast.test','test',now(),now(),now(),'{}','{}' from generate_series(1,3) value;
insert into public.profiles(id,display_name) select pg_temp.uid(value),'Private test '||value from generate_series(1,3) value;
insert into public.tenants(id,name,slug) values(pg_temp.uid(10),'Private A','s317-private-a'),(pg_temp.uid(11),'Private B','s317-private-b');
insert into public.tenant_memberships(tenant_id,user_id,role) values(pg_temp.uid(10),pg_temp.uid(1),'tenant_admin'),(pg_temp.uid(10),pg_temp.uid(2),'tenant_viewer'),(pg_temp.uid(11),pg_temp.uid(3),'tenant_admin');
insert into public.platform_memberships(user_id,role) values(pg_temp.uid(1),'platform_admin');
insert into public.tenant_feature_flags(tenant_id,flag_key,enabled,rollout_reason,changed_by) values(pg_temp.uid(10),'control_ai_agent',true,'Isolated attachment tests',pg_temp.uid(1));
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.uid(1)::text,true);
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.uid(1),'aal','aal1','role','authenticated')::text,true);
select throws_ok($$select public.set_platform_ai_config_v1('staging',0,'{"ciphertext":"synthetic","iv":"test","tag":"test"}','test-chat','test-image',false)$$,'42501',null,'key configuration requires platform reauthentication');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.uid(1),'aal','aal2','role','authenticated')::text,true);
select is(public.set_platform_ai_config_v1('staging',0,'{"ciphertext":"synthetic","iv":"test","tag":"test"}','test-chat','test-image',false)->>'configured','true','platform stores only encrypted configuration after AAL2');
select ok(not(public.get_platform_ai_config_v1('staging') ? 'encryptedKey'),'metadata never exposes encrypted or plaintext key');
select throws_ok($$select public.set_platform_ai_config_v1('staging',0,null,'test-chat','test-image',false)$$,'40001',null,'stale platform response cannot replace a rotated key');
select ok(public.begin_ai_provider_request_v1(pg_temp.uid(10),pg_temp.uid(80),pg_temp.uid(81),'staging','chat','test-chat',1),'paid checkpoint records the exact environment model and operation');
select is(public.begin_ai_provider_request_v1(pg_temp.uid(10),pg_temp.uid(80),pg_temp.uid(81),'staging','chat','test-chat',1),false,'same request admission cannot be replayed as another attempt');
select throws_ok($$select public.begin_ai_provider_request_v1(pg_temp.uid(10),pg_temp.uid(82),pg_temp.uid(81),'staging','image_generation','test-chat',1)$$,'55000',null,'image operation cannot use a mismatched configured model');
select throws_ok($$select public.finish_ai_provider_request_v1(pg_temp.uid(80),'succeeded','req-test','{}')$$,'42501',null,'browser cannot fabricate provider completion or units');
insert into public.ai_conversations(id,tenant_id,user_id) values(pg_temp.uid(20),pg_temp.uid(10),pg_temp.uid(1));
select is(public.reserve_ai_attachment_v1(pg_temp.uid(20),pg_temp.uid(30),repeat('a',64)),pg_temp.uid(30),'reserve own image before ordinary media insertion');
select is(public.reserve_ai_attachment_v1(pg_temp.uid(20),pg_temp.uid(30),repeat('a',64)),pg_temp.uid(30),'lost upload response reuses the same private attachment');
select throws_ok($$select public.reserve_ai_attachment_v1(pg_temp.uid(20),pg_temp.uid(30),repeat('b',64))$$,'42501',null,'retry identity cannot be reused for different file bytes or title');
insert into public.media_assets(id,tenant_id,kind,title,original_file_name,mime_type,status,storage_path,file_size_bytes,checksum_sha256,width,height,created_by)
values(pg_temp.uid(30),pg_temp.uid(10),'image','Private poster','poster.png','image/png','uploading','tenants/'||pg_temp.uid(10)||'/assets/'||pg_temp.uid(30)||'/original/poster.png',2048,repeat('a',64),1920,1080,pg_temp.uid(1));
select is((select count(*) from public.media_assets where id=pg_temp.uid(30)),0::bigint,'private image is absent from ordinary Media even for its owner');
select ok(private.ai_owned_storage_object('tenant-media','tenants/'||pg_temp.uid(10)||'/assets/'||pg_temp.uid(30)||'/original/poster.png'),'owner may resume its own private Storage object');
select ok(not private.ai_owned_storage_object('tenant-media','other/'||pg_temp.uid(10)||'/wrong/'||pg_temp.uid(30)||'/original/poster.png'),'similar noncanonical path cannot gain private Storage permissions');
select set_config('s317.private',(public.create_ai_proposal_v1(pg_temp.uid(10),pg_temp.uid(20),jsonb_build_object('steps',jsonb_build_array(jsonb_build_object('domain','attachment','operation','retain','commandKey',pg_temp.uid(90),'args',jsonb_build_object('id',pg_temp.uid(30))))))->>'id'),true);
select set_config('s317.privatehash',(select plan_hash from public.ai_proposals where id=current_setting('s317.private')::uuid),true);
select public.decide_ai_proposal_v1(current_setting('s317.private')::uuid,current_setting('s317.privatehash'),true);
select is(public.execute_ai_proposal_step_v1(current_setting('s317.private')::uuid,current_setting('s317.privatehash'),0)->>'status','failed','uploading media cannot pass a retention/publication step');
create temporary table private_video(value jsonb);grant all on private_video to authenticated;
insert into private_video select to_jsonb(intent) from public.create_ai_video_upload_intent_v1(pg_temp.uid(20),pg_temp.uid(10),'Private video','club.mp4','video/mp4',4096,pg_temp.uid(70)) intent;
select is((select count(*) from public.ai_attachments where conversation_id=pg_temp.uid(20)),2::bigint,'video intent reserves a separate private attachment in the same conversation');
select ok((select resumed from public.create_ai_video_upload_intent_v1(pg_temp.uid(20),pg_temp.uid(10),'Private video','club.mp4','video/mp4',4096,pg_temp.uid(70))),'same private TUS intent resumes instead of creating another asset');
insert into storage.objects(bucket_id,name,owner,metadata) select 'tenant-media',value->>'storage_path',pg_temp.uid(1),'{"size":4096,"mimetype":"video/mp4"}' from private_video;
select is((select count(*) from storage.objects where name=(select value->>'storage_path' from private_video)),1::bigint,'private owner can read its original object for TUS HEAD/resume');
select lives_ok($$select public.finalize_ai_video_upload_v1((select(value->>'upload_session_id')::uuid from private_video),pg_temp.uid(20))$$,'private video uses real metadata-verified normal finalization');
select lives_ok($$select public.finalize_ai_video_upload_v1((select(value->>'upload_session_id')::uuid from private_video),pg_temp.uid(20))$$,'lost finalization response safely resumes the same processing job');
reset role;
select is((select count(*) from public.media_processing_jobs where tenant_id=pg_temp.uid(10)),1::bigint,'video finalization queues exactly one existing processing job');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.uid(2)::text,true);
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.uid(2),'aal','aal2','role','authenticated')::text,true);
select is((select count(*) from public.ai_attachments),0::bigint,'another member cannot read private attachment metadata');
select ok(private.ai_temporary_storage_object('tenant-media','tenants/'||pg_temp.uid(10)||'/assets/'||pg_temp.uid(30)||'/original/poster.png'),'other member is denied private Storage access');
select throws_ok($$select public.begin_ai_provider_request_v1(pg_temp.uid(10),pg_temp.uid(83),pg_temp.uid(81),'staging','image_generation','test-image',1)$$,'42501',null,'AI activation does not grant viewer media-write capability');
select throws_ok($$select public.set_platform_ai_config_v1('staging',1,null,'test-chat','test-image',true)$$,'42501',null,'ordinary tenant role cannot rotate or revoke platform key');
reset role;
update public.media_assets set status='ready' where id=pg_temp.uid(30);
insert into public.tenant_custom_roles(id,tenant_id,name,capabilities) values(pg_temp.uid(60),pg_temp.uid(10),'No Media rights',array[]::text[]);
insert into public.ai_conversations(id,tenant_id,user_id) values(pg_temp.uid(22),pg_temp.uid(10),pg_temp.uid(2));
insert into public.ai_attachments(id,tenant_id,conversation_id,user_id) values(pg_temp.uid(32),pg_temp.uid(10),pg_temp.uid(22),pg_temp.uid(2));
insert into public.media_assets(id,tenant_id,kind,title,original_file_name,mime_type,status,storage_path,file_size_bytes,checksum_sha256,width,height)
values(pg_temp.uid(32),pg_temp.uid(10),'image','Earlier own upload','own.png','image/png','ready','tenants/'||pg_temp.uid(10)||'/assets/'||pg_temp.uid(32)||'/original/own.png',2048,repeat('c',64),1920,1080);
insert into storage.objects(bucket_id,name,owner) values('tenant-media','tenants/'||pg_temp.uid(10)||'/assets/'||pg_temp.uid(32)||'/original/own.png',pg_temp.uid(2));
update public.tenant_memberships set custom_role_id=pg_temp.uid(60) where tenant_id=pg_temp.uid(10) and user_id=pg_temp.uid(2);
set local role authenticated;
select ok(not private.ai_owned_storage_object('tenant-media','tenants/'||pg_temp.uid(10)||'/assets/'||pg_temp.uid(32)||'/original/own.png'),'removing Media read/write rights also revokes private owner TUS-read admission');
select is((select count(*) from storage.objects where name='tenants/'||pg_temp.uid(10)||'/assets/'||pg_temp.uid(32)||'/original/own.png'),0::bigint,'private Storage bytes are inaccessible after role revocation, even to the prior owner');
reset role;
insert into public.media_variants(asset_id,tenant_id,variant_type,mime_type,storage_path,checksum_sha256,file_size_bytes,width,height) values(pg_temp.uid(30),pg_temp.uid(10),'original','image/png','tenants/'||pg_temp.uid(10)||'/assets/'||pg_temp.uid(30)||'/original/poster.png',repeat('a',64),2048,1920,1080);
insert into public.playlists(id,tenant_id,name) values(pg_temp.uid(40),pg_temp.uid(10),'Private retention guard');
select throws_ok($$insert into public.playlist_items(tenant_id,playlist_id,media_asset_id,sort_order) values(pg_temp.uid(10),pg_temp.uid(40),pg_temp.uid(30),0)$$,'42501',null,'domain FK boundary rejects private media before explicit retention');
set local role service_role;
select ok(public.finish_ai_provider_request_v1(pg_temp.uid(80),'succeeded','req-test','{"input_tokens":0}'),'server records actual returned zero separately from unknown usage');
select is(public.finish_ai_provider_request_v1(pg_temp.uid(80),'failed','late-old-response',null),false,'late settlement cannot overwrite an already confirmed provider request');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.uid(1)::text,true);
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.uid(1),'aal','aal2','role','authenticated')::text,true);
select is(public.execute_ai_proposal_step_v1(current_setting('s317.private')::uuid,current_setting('s317.privatehash'),0)->>'status','completed','same approved step succeeds once processing is actually ready');
select is((select count(*) from public.media_assets where id=pg_temp.uid(30)),1::bigint,'only explicit confirmed retention exposes an image to ordinary Media');
select is((select status from public.ai_provider_requests where id=pg_temp.uid(80)),'succeeded','usage is queryable by tenant period and operation without prompts');
select is(public.set_platform_ai_config_v1('staging',1,'{"ciphertext":"rotated","iv":"test","tag":"test"}','test-chat','test-image',false)->>'revision','2','rotation advances configuration CAS revision');
select throws_ok($$select public.begin_ai_provider_request_v1(pg_temp.uid(10),pg_temp.uid(84),pg_temp.uid(81),'staging','chat','test-chat',1)$$,'55000',null,'old in-flight admission cannot start with a rotated key');
select is(public.set_platform_ai_config_v1('staging',2,null,'test-chat','test-image',true)->>'configured','false','revocation removes usable provider configuration');
select throws_ok($$select public.begin_ai_provider_request_v1(pg_temp.uid(10),pg_temp.uid(84),pg_temp.uid(81),'staging','chat','test-chat',3)$$,'55000',null,'revoked key admits no new paid requests');
reset role;
insert into public.media_assets(id,tenant_id,kind,title,original_file_name,mime_type,status,storage_path,file_size_bytes,checksum_sha256,width,height)
values(pg_temp.uid(31),pg_temp.uid(10),'image','Unused private poster','poster.png','image/png','ready','tenants/'||pg_temp.uid(10)||'/assets/'||pg_temp.uid(31)||'/original/poster.png',2048,repeat('b',64),1920,1080);
insert into public.ai_attachments(id,tenant_id,conversation_id,user_id,media_asset_id,expires_at) values(pg_temp.uid(31),pg_temp.uid(10),pg_temp.uid(20),pg_temp.uid(1),pg_temp.uid(31),now()-interval '1 day');
insert into public.media_variants(asset_id,tenant_id,variant_type,mime_type,storage_path,checksum_sha256,file_size_bytes,width,height) values(pg_temp.uid(31),pg_temp.uid(10),'original','image/png','tenants/'||pg_temp.uid(10)||'/assets/'||pg_temp.uid(31)||'/original/poster.png',repeat('b',64),2048,1920,1080);
update public.ai_attachments set expires_at=now()-interval '1 day' where id=pg_temp.uid(30);
set local role service_role;
select set_config('s317.lease',public.claim_ai_attachment_cleanup_v1()::text,true);
select is(current_setting('s317.lease')::jsonb->>'attachmentId',pg_temp.uid(31)::text,'cleanup claims only unretained expired image, never retained media');
select is(public.complete_ai_attachment_cleanup_v1(pg_temp.uid(31),pg_temp.uid(99)),false,'stale cleanup token cannot acknowledge deletion');
reset role;
select is((select count(*) from public.media_variants where asset_id=pg_temp.uid(31)),1::bigint,'variant metadata survives until Storage removal is acknowledged');
select throws_ok($$update public.media_assets set deleted_at=null where id=pg_temp.uid(31)$$,'55000',null,'a deleting private image cannot be restored into a concurrent reference');
set local role service_role;
select ok(public.complete_ai_attachment_cleanup_v1(pg_temp.uid(31),(current_setting('s317.lease')::jsonb->>'token')::uuid),'exact lease acknowledges Storage-first cleanup');
select is(public.complete_ai_attachment_cleanup_v1(pg_temp.uid(31),(current_setting('s317.lease')::jsonb->>'token')::uuid),false,'cleanup completion replay cannot repeat deletion');
reset role;
select is((select count(*) from public.media_variants where asset_id=pg_temp.uid(31)),0::bigint,'completed cleanup removes only temporary variant records');
select is((select count(*) from public.media_assets where id=pg_temp.uid(30) and deleted_at is null),1::bigint,'previously retained usable media remains unchanged');
select * from finish();
rollback;
